<template><div class="ui-score"><div><span>{{ label }}</span><b class="ui-numeric">{{ value }}</b></div><div class="ui-score__track" :aria-label="label" role="meter" :aria-valuenow="value" :aria-valuemin="min" :aria-valuemax="max"><i :style="{width:`${percent}%`}"/></div></div></template>
<script setup lang="ts">import{computed}from'vue';const props=withDefaults(defineProps<{label:string;value:number;min?:number;max?:number}>(),{min:0,max:100});const percent=computed(()=>Math.max(0,Math.min(100,(props.value-props.min)/(props.max-props.min||1)*100)));</script>
<style scoped>.ui-score{display:grid;gap:5px}.ui-score>div:first-child{display:flex;justify-content:space-between;color:var(--ui-text-muted);font-size:11px}.ui-score b{color:var(--ui-text);font-weight:500}.ui-score__track{height:4px;border-radius:99px;background:var(--ui-surface-strong);overflow:hidden}.ui-score__track i{display:block;height:100%;border-radius:inherit;background:var(--ui-text)}</style>
